mapper.select:
SELECT E.EXECUTION_ID, E.QUERY_ID, E.REQUEST_ID, E.REQUEST_NO, E.REQUEST_TITLE, E.QUERY_TITLE, E.DEPT_NAME AS DEPARTMENT_NAME, E.DRAFTER_NAME, E.BATCH_ID, E.STATUS, F.ROW_COUNT, E.REQUESTED_AT, E.STARTED_AT, E.DURATION_MS, F.CREATED_AT AS RESULT_CREATED_AT FROM (
) E LEFT JOIN ( SELECT EXECUTION_ID, ROW_COUNT, CREATED_AT, ROW_NUMBER() OVER ( PARTITION BY EXECUTION_ID ORDER BY CREATED_AT DESC, RESULT_ID DESC ) AS RESULT_RANK FROM QUERY_RESULT ) F ON F.EXECUTION_ID = E.EXECUTION_ID AND F.RESULT_RANK = 1 WHERE E.LATEST_RANK = 1
ORDER BY E.EXECUTION_ID DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY
